void verify(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"FAIL PROGRESSION: %s\n",why);std::exit(1);}}
struct TextPainter:Painter{
 std::vector<std::string> labels;
 void rect(float,float,float,float,uint32_t)override{} void line(float,float,float,float,uint32_t)override{} void circle(float,float,float,uint32_t)override{}
 void sprite_region(const Texture&,float,float,float,float,float,float,float,float,uint32_t)override{}
 void sprite(const Texture&,float,float,float,float,uint32_t)override{} void text(int,int,uint32_t,const char* v)override{labels.emplace_back(v);}
 bool has(const char* text)const{for(const auto& s:labels)if(s.find(text)!=std::string::npos)return true;return false;}
};
